"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { getAbstractSubgraphs, TICK_SPACING_TO_FEE } from "uniswap/src/constants/abstractContracts";
function getPoolMetadata(stable, tickSpacing) {
  if (tickSpacing !== null) {
    const tickSpacingNum = parseInt(tickSpacing);
    const fee = TICK_SPACING_TO_FEE[tickSpacingNum];
    const feePercentage = fee ? `${(fee / 1e4).toFixed(2)}%` : "Variable";
    return {
      poolType: "v3",
      feePercentage,
      tickSpacing: tickSpacingNum
    };
  }
  if (stable !== null) {
    return {
      poolType: stable ? "v2-stable" : "v2-volatile",
      feePercentage: "Variable",
      // V2 pools have variable fees
      stable
    };
  }
  return {
    poolType: "v2-volatile",
    feePercentage: "Variable"
  };
}
async function fetchVotingRewards(tokenId, userAddress, chainId) {
  const subgraphUrl = getAbstractSubgraphs(chainId).votes;
  try {
    const votesQuery = `
      query GetUserVotes($voter: String!, $tokenId: String!) {
        votes(
          where: { voter: $voter, tokenId: $tokenId }
          orderBy: timestamp
          orderDirection: desc
          first: 1000
        ) {
          tokenId
          weight
          pool {
            id
            token0 { symbol }
            token1 { symbol }
            stable
            tickSpacing
          }
          gauge { id }
          epoch { id }
          timestamp
        }
      }
    `;
    const votesResponse = await fetch(subgraphUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Origin: "https://subgraph.satsuma-prod.com",
        Referer: "https://subgraph.satsuma-prod.com/"
      },
      body: JSON.stringify({
        query: votesQuery,
        variables: {
          voter: userAddress.toLowerCase(),
          tokenId
        }
      })
    });
    if (!votesResponse.ok) {
      throw new Error(`Failed to fetch votes: ${votesResponse.status}`);
    }
    const votesData = await votesResponse.json();
    const votes = votesData.data.votes || [];
    if (votes.length === 0) {
      return {
        votedPools: [],
        rewards: [],
        canClaim: false,
        usedVeAbx: "0"
      };
    }
    const totalWeight = votes.reduce((sum, v) => sum + BigInt(v.weight), 0n);
    const gauges = Array.from(new Set(votes.map((v) => v.gauge.id)));
    const claimableRewardsQuery = `
      query GetUserClaimableRewards($tokenId: String!, $gauges: [String!]!) {
        userClaimableRewards(
          where: { tokenId: $tokenId, gauge_in: $gauges, claimableAmount_gt: "0" }
        ) {
          tokenId
          gauge {
            id
            pool {
              id
              token0 { symbol }
              token1 { symbol }
            }
          }
          token {
            id
            symbol
            decimals
          }
          rewardType
          rewardContract
          claimableAmount
        }
      }
    `;
    const claimableResponse = await fetch(subgraphUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Origin: "https://subgraph.satsuma-prod.com",
        Referer: "https://subgraph.satsuma-prod.com/"
      },
      body: JSON.stringify({
        query: claimableRewardsQuery,
        variables: {
          tokenId,
          gauges
        }
      })
    });
    if (!claimableResponse.ok) {
      throw new Error(`Failed to fetch claimable rewards: ${claimableResponse.status}`);
    }
    const claimableData = await claimableResponse.json();
    const claimableRewards = claimableData.data?.userClaimableRewards || [];
    const finalRewards = claimableRewards.map((reward) => ({
      token: {
        address: reward.token.id,
        symbol: reward.token.symbol,
        decimals: parseInt(reward.token.decimals)
      },
      amount: BigInt(reward.claimableAmount),
      type: reward.rewardType === "FEE" ? "fee" : "bribe",
      pool: {
        id: reward.gauge.pool.id,
        token0Symbol: reward.gauge.pool.token0.symbol,
        token1Symbol: reward.gauge.pool.token1.symbol
      },
      contractAddress: reward.rewardContract
    }));
    const votedPools = Array.from(
      new Set(votes.map((v) => {
        const poolMetadata = getPoolMetadata(v.pool.stable, v.pool.tickSpacing);
        return JSON.stringify({
          poolAddress: v.pool.id,
          gaugeAddress: v.gauge.id,
          ...poolMetadata
        });
      }))
    ).map((str) => JSON.parse(str));
    return {
      votedPools,
      rewards: finalRewards,
      canClaim: finalRewards.length > 0,
      usedVeAbx: (Number(totalWeight) / 1e18).toFixed(6)
    };
  } catch (error) {
    console.error("[useVotingRewardsFromSubgraph] Error fetching rewards:", error);
    throw error;
  }
}
export function useVotingRewardsFromSubgraph(lock) {
  const { address, chainId } = useAccount();
  const query = useQuery({
    queryKey: ["voting-rewards-subgraph", lock?.id, address, chainId],
    queryFn: () => fetchVotingRewards(lock.id, address, chainId),
    enabled: Boolean(lock?.id && address && chainId),
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4,
    // 1 minute
    retry: 2
  });
  return {
    votedPools: query.data?.votedPools || [],
    rewards: query.data?.rewards || [],
    canClaim: query.data?.canClaim || false,
    isLoading: query.isLoading,
    error: query.error,
    usedVeAbx: query.data?.usedVeAbx || "0",
    refetch: query.refetch
  };
}
export function formatRewardAmount(amount, decimals) {
  const value = parseFloat((Number(amount) / 10 ** decimals).toString());
  if (value === 0) return "0";
  if (value < 1e-3) return "< 0.001";
  if (value < 1) return value.toFixed(6);
  if (value < 100) return value.toFixed(4);
  return value.toFixed(2);
}
export function groupRewardsByType(rewards) {
  return {
    fees: rewards.filter((r) => r.type === "fee"),
    bribes: rewards.filter((r) => r.type === "bribe")
  };
}
export function getUniqueRewardContracts(rewards) {
  const feeContracts = /* @__PURE__ */ new Set();
  const bribeContracts = /* @__PURE__ */ new Set();
  rewards.forEach((reward) => {
    if (reward.type === "fee") {
      feeContracts.add(reward.contractAddress);
    } else {
      bribeContracts.add(reward.contractAddress);
    }
  });
  return {
    feeContracts: Array.from(feeContracts),
    bribeContracts: Array.from(bribeContracts)
  };
}
