"use strict";
import { useMemo } from "react";
import { useReadContracts, useChainId } from "wagmi";
import { getContractAddress, getContractAbi } from "uniswap/src/constants/contracts";
export function useVotedLocks(locks) {
  const chainId = useChainId();
  const voterAddress = getContractAddress(chainId, "Voter");
  const voterAbi = getContractAbi(chainId, "Voter");
  const locksKey = useMemo(() => locks.map((l) => l.id).join(","), [locks]);
  const contracts = useMemo(() => {
    return locks.map((lock) => ({
      address: voterAddress,
      abi: voterAbi,
      functionName: "usedWeights",
      args: [BigInt(lock.id)]
    }));
  }, [locksKey, voterAddress]);
  const { data, isLoading } = useReadContracts({
    contracts,
    query: {
      enabled: locks.length > 0,
      staleTime: 3e4,
      // 30 seconds
      refetchInterval: 6e4,
      // 1 minute
      refetchOnWindowFocus: false,
      refetchOnMount: false
    }
  });
  const votedLockIds = useMemo(() => {
    const lockIds = /* @__PURE__ */ new Set();
    if (data && !isLoading) {
      locks.forEach((lock, index) => {
        const usedWeights = data[index]?.result;
        if (usedWeights && usedWeights > 0n) {
          lockIds.add(lock.id);
        }
      });
    }
    return lockIds;
  }, [data, isLoading, locksKey, locks]);
  return useMemo(() => ({
    votedLockIds,
    isLoading,
    hasVoted: (lockId) => votedLockIds.has(lockId)
  }), [votedLockIds, isLoading]);
}
